// MANUAL FILE (not generated by HARIA). Safe across regenerations.
//
// Two-way translator between the backend's role attribute and the web
// inheritance hierarchy.
//
//   Backend -> Web:  Usuario entity / UsuarioViewModel / auth cookie  ->  UsuarioModel subclass
//   Web -> Backend:  UsuarioModel subclass                            ->  Rol value for the Application services
//
// Only this class knows how Rol values map to subclasses. To add a user type,
// add the enum value in the TDM, add a subclass in UsuarioModels.cs, and add
// one entry to Factories below.
using System.Security.Claims;
using WikiGames.Domain.Entities;
using WikiGames.Domain.Enums;
using WikiGames.Web.Utils.Security;
using WikiGames.Web.ViewModels;

namespace WikiGames.Web.Models.Usuarios;

public static class UsuarioModelMapper
{
    private static readonly IReadOnlyDictionary<Rol, Func<int, string, string, UsuarioModel>> Factories =
        new Dictionary<Rol, Func<int, string, string, UsuarioModel>>
        {
            [Rol.Registrado] = (id, name, email) => new RegistradoModel { Id = id, Name = name, Email = email },
            [Rol.Moderador] = (id, name, email) => new ModeradorModel { Id = id, Name = name, Email = email },
            [Rol.Administrador] = (id, name, email) => new AdministradorModel { Id = id, Name = name, Email = email },
        };

    // ---------------------------------------------------------------- Backend -> Web

    /// <summary>Builds the matching subclass from a backend Rol value.</summary>
    public static UsuarioModel Create(Rol rol, int id = 0, string name = "", string email = "") =>
        Factories.TryGetValue(rol, out var factory)
            ? factory(id, name, email)
            : throw new ArgumentOutOfRangeException(nameof(rol), rol, "No web user class is mapped to this Rol.");

    /// <summary>Server-loaded entity -> typed web user. Use this for authorization decisions.</summary>
    public static UsuarioModel FromEntity(Usuario entity)
    {
        ArgumentNullException.ThrowIfNull(entity);
        return Create(entity.RolUsuario, entity.Id, entity.Name, entity.Email);
    }

    /// <summary>Form/view data -> typed web user. Do not use client-supplied data to grant privileges.</summary>
    public static UsuarioModel FromViewModel(UsuarioViewModel model)
    {
        ArgumentNullException.ThrowIfNull(model);
        return Create(model.RolUsuario, model.Id, model.Name, model.Email);
    }

    /// <summary>
    /// Authenticated cookie -> typed web user. Returns null for anonymous users or cookies issued
    /// before this system existed (log in again). The claims were written by the server at
    /// sign-in, so they can be trusted.
    /// </summary>
    public static UsuarioModel? FromPrincipal(ClaimsPrincipal? principal)
    {
        if (principal?.Identity?.IsAuthenticated != true) return null;
        var subclass = principal.FindFirstValue(UsuarioClaimTypes.UserSubclass);
        if (!Enum.TryParse<Rol>(subclass, ignoreCase: false, out var rol) || !Factories.ContainsKey(rol)) return null;
        _ = int.TryParse(principal.FindFirstValue(ClaimTypes.Name), out var id);
        return Create(rol, id, principal.FindFirstValue(ClaimTypes.GivenName) ?? string.Empty,
            principal.FindFirstValue(ClaimTypes.Email) ?? string.Empty);
    }

    // ---------------------------------------------------------------- Web -> Backend

    /// <summary>Typed web user -> backend Rol value for the Application services (New/Modify).</summary>
    public static Rol ToRol(UsuarioModel model)
    {
        ArgumentNullException.ThrowIfNull(model);
        return model.Rol;
    }

    /// <summary>Web user class -> backend Rol, without an instance. Example: ToRol&lt;RegistradoModel&gt;().</summary>
    public static Rol ToRol<TModel>() where TModel : UsuarioModel =>
        Factories.First(pair => pair.Value(0, string.Empty, string.Empty).GetType() == typeof(TModel)).Key;

    /// <summary>Copies the typed user onto a server-loaded entity. The Id and password are never touched.</summary>
    public static void ApplyToEntity(UsuarioModel model, Usuario entity)
    {
        ArgumentNullException.ThrowIfNull(model);
        ArgumentNullException.ThrowIfNull(entity);
        entity.Name = model.Name;
        entity.Email = model.Email;
        entity.RolUsuario = model.Rol;
    }

    /// <summary>Typed web user -> the HARIA-generated UsuarioViewModel used by the views.</summary>
    public static UsuarioViewModel ToViewModel(UsuarioModel model)
    {
        ArgumentNullException.ThrowIfNull(model);
        return new UsuarioViewModel { Id = model.Id, Name = model.Name, Email = model.Email, RolUsuario = model.Rol };
    }
}

public static class UsuarioPrincipalExtensions
{
    /// <summary>The current user as a typed model, e.g. <c>User.AsUsuarioModel()</c>.</summary>
    public static UsuarioModel? AsUsuarioModel(this ClaimsPrincipal principal) => UsuarioModelMapper.FromPrincipal(principal);

    /// <summary>
    /// Inheritance-aware check: <c>User.IsUsuario&lt;ModeradorModel&gt;()</c> is true for
    /// moderators and administrators.
    /// </summary>
    public static bool IsUsuario<TModel>(this ClaimsPrincipal principal) where TModel : UsuarioModel =>
        UsuarioModelMapper.FromPrincipal(principal) is TModel;
}
